Números 7 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"A quem Moisés entregou os carros e os bois oferecidos pelos príncipes?","o":["Aos sacerdotes, filhos de Arão","Aos levitas","De volta aos príncipes","Aos anciãos do povo"],"c":1,"v":6,"e":"O versículo 6 diz que Moisés recebeu os carros e os bois e os deu aos levitas."},
{"t":"multipla","p":"Por que os filhos de Coate não receberam carros nem bois?","o":["Porque eram poucos","Porque não tinham serviço na tenda","Porque deviam levar o santuário nos ombros","Porque já tinham seus próprios carros"],"c":2,"v":9,"e":"O versículo 9 explica que estava a cargo deles o santuário, que deveriam transportar nos ombros."},
{"t":"multipla","p":"Como o Senhor mandou que os príncipes apresentassem as ofertas para a consagração do altar?","o":["Todos juntos no mesmo dia","Cada príncipe no seu dia","Só os príncipes das tribos maiores","Por meio de Moisés, em um único sacrifício"],"c":1,"v":11,"e":"No versículo 11 o Senhor diz que cada príncipe apresentaria a sua oferta, cada um no seu dia."},
{"t":"multipla","p":"Quem apresentou a oferta no primeiro dia?","o":["Natanael, pela tribo de Issacar","Elizur, pela tribo de Rúben","Naassom, pela tribo de Judá","Aira, pela tribo de Naftali"],"c":2,"v":12,"e":"O versículo 12 diz que no primeiro dia Naassom, filho de Aminadabe, ofereceu pela tribo de Judá."},
{"t":"multipla","p":"De onde vinha a voz que falava com Moisés na tenda da congregação?","o":["Do altar do holocausto","De cima do propiciatório, entre os dois querubins","Da entrada da tenda","De dentro de uma nuvem sobre o monte"],"c":1,"v":89,"e":"O versículo 89 diz que a voz falava de cima do propiciatório, sobre a arca do Testemunho, entre os dois querubins."},
{"t":"cv","p":"Os filhos de Merari receberam seus carros e bois sob a direção de Itamar, filho de Arão.","c":true,"v":8,"e":"O versículo 8 diz que os carros foram entregues aos filhos de Merari sob a direção de Itamar, filho de Arão, o sacerdote."},
{"t":"cv","p":"No segundo dia, quem apresentou a oferta foi Natanael, príncipe de Issacar.","c":true,"v":18,"e":"O versículo 18 diz que no segundo dia Natanael, filho de Zuar, príncipe de Issacar, apresentou sua oferta."},
{"t":"cv","p":"Os doze recipientes de ouro trazidos pelos príncipes estavam cheios de flor de farinha.","c":false,"v":86,"e":"O versículo 86 diz que os recipientes de ouro estavam cheios de incenso; a flor de farinha estava nos pratos e bacias de prata."}
]}

Números 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Nadabe e Abiú morreram perante o Senhor?","o":["Ofereceram fogo estranho perante o Senhor","Tocaram na arca sem permissão","Entraram no santuário sem as vestes sacerdotais","Murmuraram contra Moisés no deserto"],"c":0,"v":4,"e":"O começo do capítulo diz que eles morreram quando ofereceram fogo estranho perante o Senhor no deserto do Sinai."},
 {"t":"multipla","p":"Em lugar de quem o Senhor tomou os levitas para si?","o":["Dos sacerdotes filhos de Arão","De todo primogênito dos filhos de Israel","Dos anciãos de cada tribo","Dos homens de guerra de Israel"],"c":1,"v":12,"e":"O Senhor diz que tomou os levitas em lugar de todo primogênito que abre a madre entre os filhos de Israel."},
 {"t":"multipla","p":"Qual família levita ficou responsável pela arca, pela mesa, pelo candelabro e pelos altares?","o":["Os gersonitas","Os meraritas","Os coatitas","Os filhos de Arão"],"c":2,"v":31,"e":"Na parte sobre os coatitas, o texto diz que a responsabilidade deles será pela arca, pela mesa, pelo candelabro e pelos altares."},
 {"t":"multipla","p":"Quem foi o príncipe dos príncipes de Levi, com a superintendência do santuário?","o":["Itamar, filho de Arão","Elisafã, filho de Uziel","Eliasafe, filho de Lael","Eleazar, filho de Arão"],"c":3,"v":32,"e":"Logo depois das tarefas dos coatitas, o texto diz que Eleazar, filho de Arão, será o príncipe dos príncipes de Levi."},
 {"t":"multipla","p":"Quem acampava diante do tabernáculo, do lado do oriente?","o":["Moisés e Arão, com seus filhos","Os gersonitas","Os meraritas","Os primogênitos de Israel"],"c":0,"v":38,"e":"O texto diz que Moisés, Arão e seus filhos acamparão diante do tabernáculo, ao oriente, para o lado do nascente."},
 {"t":"cv","p":"As famílias dos gersonitas acampavam atrás do tabernáculo, a oeste.","c":true,"v":23,"e":"Na parte sobre os gersonitas, o texto diz que eles acamparão atrás do tabernáculo, a oeste."},
 {"t":"cv","p":"Os filhos de Merari acampavam ao lado do tabernáculo, do lado sul.","c":false,"v":35,"e":"O texto diz que os meraritas acamparão do lado norte, e quem ficava ao sul eram os coatitas."},
 {"t":"cv","p":"Moisés entregou o dinheiro do resgate dos primogênitos a Arão e a seus filhos.","c":true,"v":51,"e":"O fim do capítulo diz que Moisés entregou o dinheiro dos resgatados a Arão e a seus filhos, como o Senhor ordenara."}
]}

Números 6 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem podia fazer o voto de nazireu?","o":["Somente os sacerdotes","Somente os levitas","Homem ou mulher","Somente os homens"],"c":2,"v":2,"e":"O versículo 2 diz que o voto podia ser feito por alguém, \"seja homem ou mulher\"."},
 {"t":"multipla","p":"Do que o nazireu devia se abster durante o voto?","o":["De carne de animais","De vinho e de tudo que vem da videira","De pão fermentado","De azeite"],"c":1,"v":3,"e":"O versículo 3 diz que ele se absteria de vinho, de bebidas fortes e de tudo que vem das uvas."},
 {"t":"multipla","p":"O que o nazireu devia fazer com o cabelo durante o voto?","o":["Cortá-lo toda semana","Cobri-lo com um véu","Ungi-lo com azeite","Deixá-lo crescer livremente"],"c":3,"v":5,"e":"O versículo 5 diz que não passaria navalha sobre a cabeça e deixaria os cabelos crescerem livremente."},
 {"t":"multipla","p":"No oitavo dia depois de se contaminar com um morto, o que o nazireu levava ao sacerdote?","o":["Duas rolas ou dois pombinhos","Um boi sem defeito","Dois carneiros","Um cesto de pães"],"c":0,"v":10,"e":"O versículo 10 diz que no oitavo dia ele traria duas rolas ou dois pombinhos à porta da tenda da congregação."},
 {"t":"multipla","p":"Ao terminar o nazireado, o que o nazireu fazia com a cabeleira rapada?","o":["Entregava ao sacerdote para guardar","Enterrava fora do arraial","Punha no fogo debaixo do sacrifício pacífico","Lançava no rio"],"c":2,"v":18,"e":"O versículo 18 diz que ele poria a cabeleira sobre o fogo que está debaixo do sacrifício pacífico."},
 {"t":"cv","p":"O nazireu podia se contaminar com o cadáver do pai ou da mãe quando eles morressem.","c":false,"v":7,"e":"O versículo 7 diz que ele não se contaminaria nem por causa do pai, da mãe, do irmão ou da irmã."},
 {"t":"cv","p":"Se o nazireu se contaminasse, os dias anteriores do seu voto eram considerados perdidos.","c":true,"v":12,"e":"O versículo 12 diz que os dias anteriores seriam considerados perdidos, porque o nazireado foi contaminado."},
 {"t":"cv","p":"Deus mandou que Arão e seus filhos abençoassem os filhos de Israel.","c":true,"v":23,"e":"O versículo 23 diz para falar a Arão e a seus filhos: \"Assim vocês abençoarão os filhos de Israel\"."}
]}

Números 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Qual era a idade dos levitas que deviam ser contados para o serviço na tenda da congregação?","o":["Dos vinte aos cinquenta anos","Dos trinta aos cinquenta anos","Dos vinte e cinco aos sessenta anos","Dos trinta aos sessenta anos"],"c":1,"v":3,"e":"O versículo 3 manda contar a partir dos trinta anos até os cinquenta."},
 {"t":"multipla","p":"Quando o acampamento era desmontado, quem retirava o véu e cobria com ele a arca do Testemunho?","o":["Os filhos de Coate","Arão e seus filhos","Moisés e os príncipes","Os filhos de Merari"],"c":1,"v":5,"e":"O versículo 5 diz que Arão e seus filhos retiravam o véu e cobriam a arca."},
 {"t":"multipla","p":"Por que os filhos de Coate não deviam tocar nas coisas santas ao transportá-las?","o":["Para que não ficassem impuros","Para que não as quebrassem","Para que não morressem","Para que não atrasassem a viagem"],"c":2,"v":15,"e":"O versículo 15 diz que eles não tocariam nas coisas santas, para que não morressem."},
 {"t":"multipla","p":"Quem tinha o dever de cuidar do azeite da luminária, do incenso aromático e do óleo da unção?","o":["Itamar, filho de Arão","Eleazar, filho de Arão","Moisés","Os chefes dos coatitas"],"c":1,"v":16,"e":"O versículo 16 atribui esse dever a Eleazar, filho de Arão, o sacerdote."},
 {"t":"multipla","p":"O que os filhos de Merari deviam transportar?","o":["As cortinas e coberturas do tabernáculo","A arca, a mesa e o candelabro","As tábuas, os varais, as colunas e as bases do tabernáculo","O altar de ouro e os utensílios do santuário"],"c":2,"v":31,"e":"O versículo 31 diz que o encargo de Merari eram as tábuas do tabernáculo, seus varais, suas colunas e suas bases."},
 {"t":"cv","p":"O serviço dos filhos de Gérson ficava sob a direção de Eleazar, filho de Arão.","c":false,"v":28,"e":"O versículo 28 diz que a responsabilidade dos gersonitas estava sob a direção de Itamar, filho de Arão."},
 {"t":"cv","p":"Os levitas foram contados por Moisés, Arão e os príncipes de Israel.","c":true,"v":46,"e":"O versículo 46 diz que os levitas foram contados por Moisés, Arão e os príncipes de Israel."},
 {"t":"cv","p":"Ao todo, os levitas contados para o serviço somaram oito mil quinhentos e oitenta.","c":true,"v":48,"e":"O versículo 48 diz que os contados totalizaram oito mil quinhentos e oitenta."}
]}

Números 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem o Senhor mandou lançar para fora do acampamento?","o":["Todo estrangeiro","Todo leproso","Todo devedor","Todo que não guardou o sábado"],"c":1,"v":2,"e":"No versículo 2 o Senhor manda lançar fora todo leproso, quem padece fluxo e quem se tornou imundo por tocar em morto."},
 {"t":"multipla","p":"Na restituição pela culpa, quanto se acrescentava ao valor integral?","o":["Um décimo","A metade","Um quinto","O dobro"],"c":2,"v":7,"e":"O versículo 7 manda fazer a restituição integral acrescentando um quinto."},
 {"t":"multipla","p":"Se não houvesse parente próximo para receber a restituição, ela ficava com quem?","o":["Com o sacerdote","Com os pobres","Com o chefe da tribo","Com os levitas"],"c":0,"v":8,"e":"O versículo 8 diz que, nesse caso, a restituição feita ao Senhor será do sacerdote."},
 {"t":"multipla","p":"Que oferta o marido levava ao sacerdote no caso de ciúmes?","o":["Um cordeiro sem defeito","Duas rolas","Flor de farinha com azeite e incenso","Uma décima de efa de farinha de cevada"],"c":3,"v":15,"e":"O versículo 15 fala de uma décima de efa de farinha de cevada, sem azeite e sem incenso."},
 {"t":"multipla","p":"O que o sacerdote colocava na água santa, no vaso de barro?","o":["Sal","Pó do chão do tabernáculo","Cinza do altar","Azeite"],"c":1,"v":17,"e":"No versículo 17 o sacerdote toma do pó do chão do tabernáculo e o deita na água."},
 {"t":"cv","p":"Depois de ouvir o juramento de maldição, a mulher devia responder: \"Amém! Amém!\"","c":true,"v":22,"e":"O final do versículo 22 diz que a mulher dirá: Amém! Amém!"},
 {"t":"cv","p":"O sacerdote queimava no altar toda a oferta de manjares de ciúmes.","c":false,"v":26,"e":"Pelo versículo 26, o sacerdote queimava apenas um punhado da oferta sobre o altar."},
 {"t":"cv","p":"Se a mulher não estivesse contaminada, ficaria livre e poderia conceber.","c":true,"v":28,"e":"O versículo 28 diz que, se for pura, ela estará livre e poderá conceber."}
]}

Números 8 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Ao acender as sete lâmpadas, para onde elas deveriam iluminar?","o":["Defronte do candelabro","Sobre a arca da aliança","Para a entrada da tenda","Sobre o altar do incenso"],"c":0,"v":2,"e":"No versículo 2, o Senhor manda que as sete lâmpadas iluminem defronte do candelabro."},
 {"t":"multipla","p":"De que era feito o candelabro?","o":["Bronze fundido","Ouro batido, em um único bloco","Prata lavrada","Madeira de acácia coberta de ouro"],"c":1,"v":4,"e":"O versículo 4 diz que o candelabro era de ouro batido, moldado em um único bloco da base até as flores."},
