 {"t":"multipla","p":"Sobre o que os levitas colocavam as mãos?","o":["Sobre o candelabro","Sobre o altar","Sobre a cabeça de Arão","Sobre a cabeça dos novilhos"],"c":3,"v":12,"e":"O versículo 12 diz que os levitas colocariam as mãos sobre a cabeça dos novilhos antes do sacrifício."},
 {"t":"multipla","p":"Em lugar de quem o Senhor tomou os levitas?","o":["Dos primogênitos dos filhos de Israel","Dos filhos de Arão","Dos anciãos do povo","Da tribo de Judá"],"c":0,"v":18,"e":"No versículo 18, o Senhor diz que tomou os levitas em lugar de todos os primogênitos dos filhos de Israel."},
 {"t":"cv","p":"O Senhor diz que consagrou para si os primogênitos de Israel no dia em que feriu os primogênitos do Egito.","c":true,"v":17,"e":"O versículo 17 diz que, no dia em que feriu todo primogênito no Egito, o Senhor consagrou para si os primogênitos de Israel."},
 {"t":"cv","p":"Foi Moisés quem apresentou os levitas como oferta movida perante o Senhor.","c":false,"v":21,"e":"O versículo 21 diz que foi Arão quem apresentou os levitas como oferta movida e fez expiação por eles."},
 {"t":"cv","p":"Os levitas começavam o serviço na tenda da congregação a partir dos trinta anos.","c":false,"v":24,"e":"O versículo 24 diz que os levitas entravam no serviço a partir dos vinte e cinco anos."}
]}
